exercises.schema:
CREATE TABLE orders (
  id        int PRIMARY KEY,
  seller_id int NOT NULL,
  amount    numeric(10,2),
  status    text NOT NULL CHECK (status IN ('paid', 'refunded', 'pending'))
);

CREATE TABLE tasks (
  id    int PRIMARY KEY,
  team  text,
  hours int
);

CREATE TABLE customers (
  id   int PRIMARY KEY,
  name text NOT NULL
);
CREATE TABLE orders (
  id          int PRIMARY KEY,
  customer_id int NOT NULL REFERENCES customers(id),
  status      text
);

